public class StringReverser {

    public String reverseWithStringBuilder(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }
        return new StringBuilder(input).reverse().toString();
    }

    public String reverseManually(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }
        var result = new StringBuilder(input.length());
        for (int i = input.length() - 1; i >= 0; i--) {
            result.append(input.charAt(i));  // Build backwards
        }
        return result.toString();
    }

    public String reverseWithCharArray(String input) {
        char[] chars = input.toCharArray();
        int left = 0, right = chars.length - 1;
        while (left < right) {
            char temp = chars[left];
            chars[left++] = chars[right];
            chars[right--] = temp;  // Swap in place
        }
        return new String(chars);
    }
}

import java.util.*;

public class CharacterFrequencyCounter {

    public Map<Character, Integer> countWithHashMap(String input) {
        var frequencyMap = new HashMap<Character, Integer>();
        for (char c : input.toCharArray()) {
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }
        return frequencyMap;
    }

    public Map<Character, Integer> countWithMerge(String input) {
        var frequencyMap = new HashMap<Character, Integer>();
        for (char c : input.toCharArray()) {
            frequencyMap.merge(c, 1, Integer::sum);  // Cleaner update
        }
        return frequencyMap;
    }

    public int[] countLowercaseLetters(String input) {
        var frequency = new int[26];  // a-z only
        for (char c : input.toLowerCase().toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                frequency[c - 'a']++;  // Map 'a'->0, 'b'->1, etc.
            }
        }
        return frequency;
    }
}

import java.util.*;

public class AnagramChecker {

    public boolean isAnagramSorting(String s1, String s2) {
        if (s1.length() != s2.length()) {
            return false;  // Fast rejection
        }
        char[] chars1 = s1.toCharArray();
        char[] chars2 = s2.toCharArray();
        Arrays.sort(chars1);
        Arrays.sort(chars2);
        return Arrays.equals(chars1, chars2);
    }

    public boolean isAnagramFrequency(String s1, String s2) {
        if (s1.length() != s2.length()) {
            return false;
        }
        var frequencyMap = new HashMap<Character, Integer>();
        for (char c : s1.toCharArray()) {
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }
        for (char c : s2.toCharArray()) {
            int count = frequencyMap.getOrDefault(c, 0);
            if (count == 0) return false;  // Character not in s1
            frequencyMap.put(c, count - 1);
        }
        return true;  // All counts decremented to zero
    }
}

import java.util.*;

public class NonRepeatingCharFinder {

    public Character findFirstNonRepeating(String input) {
        if (input == null || input.isEmpty()) {
            return null;
        }
        var frequencyMap = new HashMap<Character, Integer>();

        // First pass: build frequency map
        for (char c : input.toCharArray()) {
            frequencyMap.put(c, frequencyMap.getOrDefault(c, 0) + 1);
        }

        // Second pass: find first with count 1
        for (char c : input.toCharArray()) {
            if (frequencyMap.get(c) == 1) {
                return c;  // Return first unique character
            }
        }
        return null;  // All characters repeat
    }

    public Character findFirstNonRepeatingArray(String input) {
        var frequency = new int[26];  // Lowercase a-z only
        var normalized = input.toLowerCase();
        for (char c : normalized.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                frequency[c - 'a']++;
            }
        }
        for (char c : normalized.toCharArray()) {
            if (c >= 'a' && c <= 'z' && frequency[c - 'a'] == 1) {
                return c;
            }
        }
        return null;
    }
}

import java.util.*;

public class DuplicateRemover {

    public String removeDuplicatesLinkedHashSet(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }
        var seen = new LinkedHashSet<Character>();
        for (char c : input.toCharArray()) {
            seen.add(c);  // Automatically rejects duplicates, preserves order
        }
        var result = new StringBuilder(seen.size());
        for (char c : seen) {
            result.append(c);
        }
        return result.toString();
    }

    public String removeDuplicatesStringBuilder(String input) {
        if (input == null || input.isEmpty()) {
            return input;
        }
        var result = new StringBuilder();
        for (char c : input.toCharArray()) {
            if (result.indexOf(String.valueOf(c)) == -1) {  // O(n) search per character
                result.append(c);
            }
        }
        return result.toString();
    }

    public String removeDuplicatesWithSet(String input) {
        var seen = new LinkedHashSet<Character>();
        for (char c : input.toCharArray()) {
            seen.add(c);
        }
        return seen.stream()
                .map(String::valueOf)
                .reduce("", String::concat);  // Collect back to String
    }
}
